@aurel32 You are right, I have removed the STOP2 mode from board dts, and then I2C works in LPM.
In fact, I am using I2C2 and it will lose the clock in STOP2 mode.

What I want is to work back after wake up from STOP2 mode. So I have called the I2C driver init(`i2c_stm32_init()`) after wake up, then it works well.
@erwango I think there might be some way to re-init enabled clocks or call driver init functions after wake up from suspend in power management. E.g. can we add something to enable clocks in `power.c`. I have no clue what's the best way.

```
__weak void pm_power_state_exit_post_ops(struct pm_state_info info)
{
	switch (info.state) {
	case PM_STATE_SUSPEND_TO_IDLE:
		LL_LPM_DisableSleepOnExit();
		LL_LPM_EnableSleep();
		/* need to restore the clock */
		stm32_clock_control_init(NULL);

		/* Add something */
#ifdef CONFIG_I2C_STM32
		// call i2c_stm32_init or enable i2c clocks due to dts
#endif

		break;
	case PM_STATE_SOFT_OFF:
		/* Nothing to do. */
		break;
	default:
		LOG_DBG("Unsupported power substate-id %u", info.state);
		break;
	}

	/*
	 * System is now in active mode.
	 * Reenable interrupts which were disabled
	 * when OS started idling code.
	 */
	irq_unlock(0);
}
```

As suggested @honestech74 re-configure the i2c timings on `PM_DEVICE_ACTION_RESUME`.
It would be nice to introduce the change in a PR.

What i've done so far (don't know if it's good practice): 
```
#if defined(CONFIG_SOC_SERIES_STM32WLX)
static int i2c_stm32_reinit_timing(const struct device *dev)
{
	int ret;
	const struct i2c_stm32_config *cfg = dev->config;
	const struct device *const clk = DEVICE_DT_GET(STM32_CLOCK_CONTROL_NODE);
	uint32_t i2c_clock = 0U;
	
	if (IS_ENABLED(STM32_I2C_DOMAIN_CLOCK_SUPPORT) && (cfg->pclk_len > 1)) {
		if (clock_control_get_rate(clk, (clock_control_subsys_t)&cfg->pclken[1],
					   &i2c_clock) < 0) {
			LOG_ERR("Failed call clock_control_get_rate(pclken[1])");
			return -EIO;
		}
	} else {
		if (clock_control_get_rate(clk, (clock_control_subsys_t)&cfg->pclken[0],
					   &i2c_clock) < 0) {
			LOG_ERR("Failed call clock_control_get_rate(pclken[0])");
			return -EIO;
		}
	}

#ifdef CONFIG_PM_DEVICE_RUNTIME
	ret = clock_control_on(clk, (clock_control_subsys_t)&cfg->pclken[0]);
	if (ret < 0) {
		LOG_ERR("failure Enabling I2C clock");
		return ret;
	}
#endif

	ret = stm32_i2c_configure_timing(dev, i2c_clock);

	return ret;
}
#endif`

```
And call it in `i2c_stm32_pm_action` on `PM_DEVICE_ACTION_RESUME`
